import axios from "axios";

const express = require('express');

const app = express();
const port = 3000;

app.get('/get-exercise/:muscleChoice', async (req, res) => {
  const muscleChoice = req.params.muscleChoice;
  
  const options = {
    method: "GET",
    url: `https://exercisedb.p.rapidapi.com/exercises/bodyPart/${muscleChoice}`,
    headers: {
      "X-RapidAPI-Key": "57996be828msh986f446112d7c93p1e56fajsn95c27087f48a",
      "X-RapidAPI-Host": "exercisedb.p.rapidapi.com",
    },
  };

  try {
    const response = await axios(options);
    res.json(response.data);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

app.listen(port, () => {
  console.log(`API running on http://localhost:${port}`);
});


export default getData;
